                errcode=Codes.INVALID_PARAM,
            )
        if type(burst_count) is not int or burst_count < 0:
            raise SynapseError(
                HTTPStatus.BAD_REQUEST,
                "%r parameter must be a positive int" % (burst_count,),
                errcode=Codes.INVALID_PARAM,
