class GitHubOAuthenticator(OAuthenticator):
    github_organization_whitelist = Set(
        config=True,
        help="Automatically whitelist members of selected organizations",
    )
    @gen.coroutine
    def authenticate(self, handler, data=None):
        """We set up auth_state based on additional GitHub info if we
        receive it.
        """
        code = handler.get_argument("code")
        http_client = AsyncHTTPClient()
        params = dict(
            client_id=self.client_id,
            client_secret=self.client_secret,
            code=code
        )
        url = url_concat("%s://%s/login/oauth/access_token" % (GITHUB_PROTOCOL, GITHUB_HOST),
                         params)
        req = HTTPRequest(url,
                          method="POST",
                          headers={"Accept": "application/json"},
                          body=''
                          )
        resp = yield http_client.fetch(req)
        resp_json = json.loads(resp.body.decode('utf8', 'replace'))
        access_token = resp_json['access_token']
        req = HTTPRequest("%s://%s/user" % (GITHUB_PROTOCOL, GITHUB_API),
                          method="GET",
                          headers=_api_headers(access_token)
                          )
        resp = yield http_client.fetch(req)
        resp_json = json.loads(resp.body.decode('utf8', 'replace'))
        username = resp_json["login"]
        if not username:
            return None
        if self.github_organization_whitelist:
            for org in self.github_organization_whitelist:
                user_in_org = yield self._check_organization_whitelist(org, username, access_token)
                if user_in_org:
                    break
            else:
                self.log.warning("User %s is not in org whitelist", username)
                return None
        userdict = {"name": username}
        userdict["auth_state"] = auth_state = {}
        auth_state['access_token'] = access_token
        auth_state['github_user'] = resp_json
        return userdict
    @gen.coroutine
    def _check_organization_whitelist(self, org, username, access_token):
        http_client = AsyncHTTPClient()
        headers = _api_headers(access_token)
        next_page = "%s://%s/orgs/%s/members" % (GITHUB_PROTOCOL, GITHUB_API, org)
        while next_page:
            req = HTTPRequest(next_page, method="GET", headers=headers)
            resp = yield http_client.fetch(req)
            resp_json = json.loads(resp.body.decode('utf8', 'replace'))
            next_page = next_page_from_links(resp)
            for entry in resp_json:
                if username == entry['login']:
                    return True
        return False
def parse_header_links(value):
    """Return a dict of parsed link headers proxies.
    i.e. Link: <http:/.../front.jpeg>; rel=front; type="image/jpeg",<http://.../back.jpeg>; rel=back;type="image/jpeg"
    :rtype: list
    """
    links = []
    replace_chars = ' \'"'
    for val in re.split(', *<', value):
        try:
            url, params = val.split(';', 1)
        except ValueError:
            url, params = val, ''
        link = {'url': url.strip('<> \'"')}
        for param in params.split(';'):
            try:
                key, value = param.split('=')
            except ValueError:
                break
            link[key.strip(replace_chars)] = value.strip(replace_chars)
        links.append(link)
    return links
def next_page_from_links(response):
    """Return the url of the 'next' link header as a string.
    Return None if no link header called 'next' is found.
    Both Gitlab and Github use link headers for pagination:
        https://docs.gitlab.com/ee/api/README.html
        https://developer.github.com/v3/
    """
    link_header = response.headers.get('Link')
    if not link_header:
        return None
    for link in parse_header_links(link_header):
        if link.get('rel') == 'next':
            return link['url']
    return None

class UserManager(GroupChangeListener):
    def login_user(self, user):
        self._cleanup_sessions()
        if user is None or user.is_anonymous:
            return
        if isinstance(user, LocalProxy):
            user = user._get_current_object()
        if not isinstance(user, User):
            return None
        if not isinstance(user, SessionUser):
            user = SessionUser(user)
        self._session_users_by_session[user.session] = user
        userid = user.get_id()
        if userid not in self._sessionids_by_userid:
            self._sessionids_by_userid[userid] = set()
        self._sessionids_by_userid[userid].add(user.session)
        for listener in self._login_status_listeners:
            try:
                listener.on_user_logged_in(user)
            except Exception:
                self._logger.exception(
                    f"Error in on_user_logged_in on {listener!r}",
                    extra={"callback": fqcn(listener)},
                )
        self._logger.info(f"Logged in user: {user.get_id()}")
        return user
    def logout_user(self, user, stale=False):
                listener.on_user_logged_out(user, stale=stale)
    def _cleanup_sessions(self):
        for session, user in list(self._session_users_by_session.items()):
            if not isinstance(user, SessionUser):
                continue
            if user.created + (24 * 60 * 60) < time.monotonic():
                self._logger.info(
                    "Cleaning up user session {} for user {}".format(
                        session, user.get_id()
                    )
                )
                self.logout_user(user, stale=True)
    def add_user(self, username, password, active, permissions, groups, overwrite=False):
        pass
    def validate_user_session(self, userid, session):
        if session in self._session_users_by_session:
            user = self._session_users_by_session[session]
            return userid == user.get_id()
        return False
    def find_sessions_for(self, matcher):
        result = []
        for user in self.get_all_users():
            if matcher(user):
                try:
                    session_ids = self._sessionids_by_userid[user.get_id()]
                    for session_id in session_ids:
                        try:
                            result.append(self._session_users_by_session[session_id])
                        except KeyError:
                            continue
                except KeyError:
                    pass
        return result
    def _trigger_on_user_modified(self, user):
        if isinstance(user, str):
            users = []
            try:
                session_ids = self._sessionids_by_userid[user]
                for session_id in session_ids:
                    try:
                        users.append(self._session_users_by_session[session_id])
                    except KeyError:
                        continue
            except KeyError:
                return
        elif isinstance(user, User) and not isinstance(user, SessionUser):
            users = self.find_sessions_for(lambda u: u.get_id() == user.get_id())
        elif isinstance(user, User):
            users = [user]
        else:
            return
        for listener in self._login_status_listeners:
            try:
                for user in users:
                    listener.on_user_modified(user)
            except Exception:
                self._logger.exception(
                    f"Error in on_user_modified on {listener!r}",
                    extra={"callback": fqcn(listener)},
                )
