def can_be_array(arg):
    if arg.type == 'char' and arg.derefcnt == 2:
        return True
    if arg.type == 'void' and arg.derefcnt == 2:
        return True
def fix_bad_arg_names(func, arg):
    if arg.name == 'str':
        return 'str_'
    if arg.name == 'len':
        return 'length'
    if arg.name == 'repr':
        return 'repr_'
    if func.name == 'open' and arg.name == 'vararg':
        return 'mode'
