    decoder = {
        "cbor": decode_cbor,
        "json": decode_json,
        "msgpack": decode_msgpack,
        "toml": decode_toml,
        "yaml": decode_yaml,
    }
    if input_format not in decoder:
        msg = f"Unknown input format: {input_format}"
        raise ValueError(msg)
    return decoder[input_format](input_data)
