                'd) Download',
                'l) List',
                ' u) Update',
                'c) Config',
                'h) Help',
                'q) Quit',
            )
            user_input = input('Downloader> ').strip()
            if not user_input:
                print()
                continue
            command = user_input.lower().split()[0]
            args = user_input.split()[1:]
