                    }
                ),
                403,
            )
        if os.path.exists(target_path):
            try:
                rmtree(target_path)
            except Exception:
                return jsonify({"message": "Deletion failed."}), 500
        else:
            return jsonify({"message": "No file or directory at path %s" % path}), 500
        return jsonify({"message": "Success"})
