    if '&' not in text:
        return text
    new_text = []
    for part in next_possible_entity(text):
        if not part:
            continue
        if part.startswith('&'):
            entity = match_entity(part)
            if entity is not None:
                new_text.append(convert_entity(entity))
                remainder = part[len(entity) + 2:]
                if part:
                    new_text.append(remainder)
                continue
        new_text.append(part)
