class Slice(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        src, start, length = args
        if src.value in ADHOC_SLICE_NODE_MACROS:
            return _build_adhoc_slice_node(src, start, length, context)
        is_bytes32 = is_base_type(src.typ, "bytes32")
        if src.location is None:
            assert is_bytes32, src
            src = ensure_in_memory(src, context)
        with src.cache_when_complex("src") as (b1, src), start.cache_when_complex("start") as (
            b2,
            start,
        ), length.cache_when_complex("length") as (b3, length):
            if is_bytes32:
                src_maxlen = 32
            else:
                src_maxlen = src.typ.maxlen
            dst_maxlen = length.value if length.is_literal else src_maxlen
            buflen = dst_maxlen
            if src.location == STORAGE:
                buflen += 32
            assert isinstance(src.typ, ByteArrayLike) or is_bytes32
            if isinstance(src.typ, StringType):
                dst_typ = StringType(maxlen=dst_maxlen)
            else:
                dst_typ = ByteArrayType(maxlen=dst_maxlen)
            buf = context.new_internal_variable(ByteArrayType(buflen))
            dst = IRnode.from_list(buf, typ=dst_typ, location=MEMORY)
            dst_data = bytes_data_ptr(dst)
            if is_bytes32:
                src_len = 32
                src_data = src
            else:
                src_len = get_bytearray_length(src)
                src_data = bytes_data_ptr(src)
            if src.location == STORAGE:
                copy_src = IRnode.from_list(
                    ["add", src_data, ["div", start, 32]],
                    location=src.location,
                )
                copy_dst = IRnode.from_list(
                    ["sub", dst_data, ["mod", start, 32]], location=dst.location
                )
                copy_len = ["add", length, ["mul", 32, ["iszero", ["iszero", ["mod", start, 32]]]]]
                copy_maxlen = buflen
            else:
                copy_src = add_ofst(src_data, start)
                copy_dst = dst_data
                copy_len = length
                copy_maxlen = buflen
            do_copy = copy_bytes(
                copy_dst,
                copy_src,
                copy_len,
                copy_maxlen,
            )
            ret = [
                "seq",
                ["assert", ["le", ["add", start, length], src_len]],
                do_copy,
                ["mstore", dst, length],
                dst,
            ]
            ret = IRnode.from_list(ret, typ=dst_typ, location=MEMORY)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
def _get_element_ptr_tuplelike(parent, key):
    typ = parent.typ
    assert isinstance(typ, TupleLike)
    if isinstance(typ, StructType):
        assert isinstance(key, str)
        subtype = typ.members[key]
        attrs = list(typ.tuple_keys())
        index = attrs.index(key)
        annotation = key
    else:
        assert isinstance(key, int)
        subtype = typ.members[key]
        attrs = list(range(len(typ.members)))
        index = key
        annotation = None
    if parent.value == "~empty":
        return IRnode.from_list("~empty", typ=subtype)
    if parent.value == "multi":
        assert parent.encoding != Encoding.ABI, "no abi-encoded literals"
        return parent.args[index]
    ofst = 0
    if parent.encoding == Encoding.ABI:
        if parent.location == STORAGE:
            raise CompilerPanic("storage variables should not be abi encoded")
        member_t = typ.members[attrs[index]]
        for i in range(index):
            member_abi_t = typ.members[attrs[i]].abi_type
            ofst += member_abi_t.embedded_static_size()
        return _getelemptr_abi_helper(parent, member_t, ofst)
    if parent.location.word_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].storage_size_in_words
    elif parent.location.byte_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].memory_bytes_required
    else:
        raise CompilerPanic(f"bad location {parent.location}")
    return IRnode.from_list(
        add_ofst(parent, ofst),
        typ=subtype,
        location=parent.location,
        encoding=parent.encoding,
        annotation=annotation,
    )
def parse_type(item, sigs, custom_structs, enums):
    def _sanity_check(x):
        assert x, "typechecker missed this"
    def _parse_type(item):
        return parse_type(item, sigs, custom_structs, enums)
    def FAIL():
        raise InvalidType(f"{item.id}", item)
    if isinstance(item, vy_ast.Name):
        if item.id in BASE_TYPES:
            return BaseType(item.id)
        elif item.id in sigs:
            return InterfaceType(item.id)
        elif item.id in enums:
            return EnumType(item.id, enums[item.id].members.copy())
        elif item.id in custom_structs:
            return make_struct_type(item.id, sigs, custom_structs[item.id], custom_structs, enums)
        else:
            FAIL()
    elif isinstance(item, vy_ast.Call) and isinstance(item.func, vy_ast.Name):
        if item.func.id == "address":
            if sigs and item.args[0].id in sigs:
                return InterfaceType(item.args[0].id)
        elif item.func.id in custom_structs:
            return make_struct_type(item.id, sigs, custom_structs[item.id], custom_structs, enums)
        elif item.func.id == "immutable":
            if len(item.args) != 1:
                raise ArgumentException("Invalid number of arguments to `immutable`", item)
            return BaseType(item.args[0].id)
        else:
            FAIL()
    elif isinstance(item, vy_ast.Subscript):
        if isinstance(item.slice.value, vy_ast.Int):
            length = item.slice.value.n
            _sanity_check(isinstance(length, int) and length > 0)
            if getattr(item.value, "id", None) == "Bytes":
                return ByteArrayType(length)
            elif getattr(item.value, "id", None) == "String":
                return StringType(length)
            else:
                value_type = _parse_type(item.value)
                return SArrayType(value_type, length)
        elif item.value.id == "DynArray":
            _sanity_check(isinstance(item.slice.value, vy_ast.Tuple))
            length = item.slice.value.elements[1].n
            _sanity_check(isinstance(length, int) and length > 0)
            value_type_annotation = item.slice.value.elements[0]
            value_type = _parse_type(value_type_annotation)
            return DArrayType(value_type, length)
        elif item.value.id in ("HashMap",) and isinstance(item.slice.value, vy_ast.Tuple):
            key_type = _parse_type(item.slice.value.elements[0])
            value_type = _parse_type(item.slice.value.elements[1])
            return MappingType(key_type, value_type)
        else:
            FAIL()
    elif isinstance(item, vy_ast.Tuple):
        member_types = [_parse_type(t) for t in item.elements]
        return TupleType(member_types)
    else:
        FAIL()
class FunctionNodeVisitor(VyperNodeVisitorBase):
    def visit_Return(self, node):
        values = node.value
        if values is None:
            if self.func.return_type:
                raise FunctionDeclarationException("Return statement is missing a value", node)
            return
        elif self.func.return_type is None:
            raise FunctionDeclarationException("Function does not return any values", node)
        if isinstance(values, vy_ast.Tuple):
            values = values.elements
            if not isinstance(self.func.return_type, TupleDefinition):
                raise FunctionDeclarationException("Function only returns a single value", node)
            if self.func.return_type.length != len(values):
                raise FunctionDeclarationException(
                    f"Incorrect number of return values: "
                    f"expected {self.func.return_type.length}, got {len(values)}",
                    node,
                )
            for given, expected in zip(values, self.func.return_type.value_type):
                validate_expected_type(given, expected)
        else:
            validate_expected_type(values, self.func.return_type)
        self.expr_visitor.visit(node.value)
def parse_body(code, context, ensure_terminated=False):
    if not isinstance(code, list):
        return parse_stmt(code, context)
    ir_node = ["seq"]
    for stmt in code:
        ir = parse_stmt(stmt, context)
        ir_node.append(ir)
    if ensure_terminated and context.return_type is None and not _is_terminated(code):
        ir_node.append(parse_stmt(vy_ast.Return(value=None), context))
    ir_node.append("pass")
    return IRnode.from_list(ir_node)

class ImportZipProject():
    def read_zip(self,zip_file_path,create_user):
        self.temp_dir = zip_file_path[:-3]
        os.mkdir(self.temp_dir)
        shutil.unpack_archive(zip_file_path, extract_dir=self.temp_dir)
        for root, dirs, files in os.walk(self.temp_dir):
            for dir in dirs:
                try:
                    new_dir = dir.encode('cp437').decode('gbk')
                except:
                    new_dir = dir.encode('utf-8').decode('utf-8')
                os.rename(os.path.join(root, dir), os.path.join(root, new_dir))
            for file in files:
                try:
                    new_file = file.encode('cp437').decode('gbk')
                except:
                    new_file = file.encode('utf-8').decode('utf-8')
                os.rename(os.path.join(root, file), os.path.join(root, new_file))
        try:
            with open(os.path.join(self.temp_dir ,'mrdoc.yaml'),'r',encoding='utf-8') as yaml_file:
                yaml_str = yaml.load(yaml_file.read())
                project_name = yaml_str['project_name'] \
                    if 'project_name' in yaml_str.keys() else zip_file_path[:-4].split('/')[-1]
                project_desc = yaml_str['project_desc'] if 'project_desc' in yaml_str.keys() else ''
                project_role = yaml_str['project_role'] if 'project_role' in yaml_str.keys() else 1
                editor_mode = yaml_str['editor_mode'] if 'editor_mode' in yaml_str.keys() else 1
                project_toc = yaml_str['toc']
                toc_item_list = []
                for toc in project_toc:
                    item = {
                        'name': toc['name'],
                        'file': toc['file'],
                        'parent': 0,
                    }
                    toc_item_list.append(item)
                    if 'children' in toc.keys():
                        for b in toc['children']:
                            item = {
                                'name': b['name'],
                                'file': b['file'],
                                'parent': toc['name']
                            }
                            toc_item_list.append(item)
                            if 'children' in b.keys():
                                for c in b['children']:
                                    item = {
                                        'name': c['name'],
                                        'file': c['file'],
                                        'parent': b['name']
                                    }
                                    toc_item_list.append(item)
        except:
            logger.error(_("未发现yaml文件"))
            project_name = zip_file_path[:-4].split('/')[-1]
            project_desc = ''
            project_role = 1
            editor_mode = 1
            project_toc = False
        with transaction.atomic():
            save_id = transaction.savepoint()
            try:
                project = Project.objects.create(
                    name=project_name,
                    intro=project_desc,
                    role=project_role,
                    create_user=create_user
                )
                if project_toc is False:
                    for f in os.listdir(self.temp_dir):
                        if f.endswith('.md'):
                            with open(os.path.join(self.temp_dir,f),'r',encoding='utf-8') as md_file:
                                md_content = md_file.read()
                                md_content = self.operat_md_media(md_content,create_user)
                                doc = Doc.objects.create(
                                    name = f[:-3],
                                    pre_content = md_content,
                                    top_doc = project.id,
                                    status = 0,
                                    editor_mode = editor_mode,
                                    create_user = create_user
                                )
                else:
                    for i in toc_item_list:
                        with open(os.path.join(self.temp_dir,i['file']),'r',encoding='utf-8') as md_file:
                            md_content = md_file.read()
                            md_content = self.operat_md_media(md_content, create_user)
                            doc = Doc.objects.create(
                                name=i['name'],
                                pre_content=md_content,
                                top_doc=project.id,
                                parent_doc = (Doc.objects.get(top_doc=project.id,name=i['parent'])).id \
                                    if i['parent'] != 0 else 0,
                                status=0,
                                editor_mode=editor_mode,
                                create_user=create_user
                            )
            except:
                logger.exception(_("解析导入文件异常"))
                transaction.savepoint_rollback(save_id)
            transaction.savepoint_commit(save_id)
        try:
            shutil.rmtree(self.temp_dir)
            os.remove(zip_file_path)
            return project.id
        except:
            logger.exception(_("删除临时文件异常"))
            return None
    def operat_md_media(self,md_content,create_user):
        pattern = r"\!\[.*?\]\(.*?\)"
        media_list = re.findall(pattern, md_content)
        if len(media_list) > 0:
            for media in media_list:
                media_filename = media.split("(")[-1].split(")")[0]
                if media_filename.startswith("./") or media_filename.startswith("/"):
                    file_suffix = media_filename.split('.')[-1]
                    if file_suffix.lower() not in settings.ALLOWED_IMG:
                        continue
                    if media_filename.startswith("./"):
                        temp_media_file_path = os.path.join(self.temp_dir,media_filename[2:])
                    else :
                        temp_media_file_path = os.path.join(self.temp_dir, media_filename[1:])
                    if os.path.exists(temp_media_file_path):
                        dir_name = upload_generation_dir()
                        copy2_filename = dir_name + '/' + str(time.time()) + '.' + file_suffix
                        new_media_file_path = shutil.copy2(
                            temp_media_file_path,
