        except ValueError:
            raise InvalidQueryException('Invalid parameter: must contain three elements')
        try:
            serial_start, serial_end = serial_range.split('-')
            serial_start = int(serial_start)
            if serial_end == 'LAST':
                serial_end = None
            else:
                serial_end = int(serial_end)
