    if silent:
        return True
    initial = offset = state.sCount[startLine] + 1
    try:
        second_char_code: int | None = state.srcCharCode[pos]
    except IndexError:
        second_char_code = None
    if second_char_code == 0x20:
        pos += 1
        initial += 1
        offset += 1
        adjustTab = False
        spaceAfterMarker = True
    elif second_char_code == 0x09:
        spaceAfterMarker = True
        if (state.bsCount[startLine] + offset) % 4 == 3:
            pos += 1
            initial += 1
            offset += 1
            adjustTab = False
        else:
            adjustTab = True
    else:
        spaceAfterMarker = False
    oldBMarks = [state.bMarks[startLine]]
    state.bMarks[startLine] = pos
    while pos < max:
        ch = state.srcCharCode[pos]
        if isSpace(ch):
            if ch == 0x09:
                offset += (
                    4
                    - (offset + state.bsCount[startLine] + (1 if adjustTab else 0)) % 4
                )
            else:
                offset += 1
        else:
            break
        pos += 1
    oldBSCount = [state.bsCount[startLine]]
    state.bsCount[startLine] = (
        state.sCount[startLine] + 1 + (1 if spaceAfterMarker else 0)
    )
    lastLineEmpty = pos >= max
    oldSCount = [state.sCount[startLine]]
    state.sCount[startLine] = offset - initial
    oldTShift = [state.tShift[startLine]]
    state.tShift[startLine] = pos - state.bMarks[startLine]
    terminatorRules = state.md.block.ruler.getRules("blockquote")
    oldParentType = state.parentType
    state.parentType = "blockquote"
    nextLine = startLine + 1
    while nextLine < endLine:
        isOutdented = state.sCount[nextLine] < state.blkIndent
        pos = state.bMarks[nextLine] + state.tShift[nextLine]
        max = state.eMarks[nextLine]
        if pos >= max:
            break
        evaluatesTrue = state.srcCharCode[pos] == 0x3E and not isOutdented
        pos += 1
