    pos = state.bMarks[startLine] + state.tShift[startLine]
    maximum = state.eMarks[startLine]
    if state.sCount[startLine] - state.blkIndent >= 4:
        return False
    marker = state.srcCharCode[pos]
    pos += 1
    if marker != 0x2A and marker != 0x2D and marker != 0x5F:
        return False
